// Embed only reviewed local PNGs; no runtime package or image requests.
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const root = new URL('./', import.meta.url);
const manifest = JSON.parse(readFileSync(new URL('provenance.json', root), 'utf8'));
const illustrated = JSON.parse(readFileSync(new URL('illustrated.json', root), 'utf8'));
const xp = JSON.parse(readFileSync(new URL('xp.json', root), 'utf8'));
for (const item of [...manifest.fugueFiles, ...manifest.classicSources, ...illustrated.sources]) {
  if (createHash('sha256').update(readFileSync(new URL(item.file, root))).digest('hex') !== item.sha256) throw new Error(`Source changed: ${item.file}`);
}
const images = {};
const sizes = {};
for (const file of new Set(Object.values(manifest.glyphs))) {
  const bytes = readFileSync(new URL(file, root));
  const name = file.split('/').at(-1).replace(/\.png$/, '');
  if (!file.startsWith('xp/') || ![...xp.tools, ...xp.commands].includes(name)) throw new Error(`Unlisted active Paint icon: ${file}`);
  const size = xp.tools.includes(name) ? xp.nativeSizes.tools : xp.nativeSizes.commands;
  if (!bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) || bytes.readUInt32BE(16) !== size || bytes.readUInt32BE(20) !== size) throw new Error(`Not a ${size}px PNG: ${file}`);
  images[file] = `data:image/png;base64,${bytes.toString('base64')}`;
  sizes[file] = size;
}
const output = `// Generated by vendor/paint-icons/generate.mjs. Original Windows XP-style Paint artwork, MIT.\n// See vendor/paint-icons/README.md and public/THIRD_PARTY_NOTICES.txt.\nconst images: Readonly<Record<string, string>> = Object.freeze(${JSON.stringify(images, null, 2)});\nconst glyphs: Readonly<Record<string, string>> = Object.freeze(${JSON.stringify(manifest.glyphs, null, 2)});\nexport const paintBitmaps: Readonly<Record<string, string>> = Object.freeze(Object.fromEntries(Object.entries(glyphs).map(([name, file]) => [name, images[file]!])));\n`;
const sizeOutput = `export const paintBitmapSizes: Readonly<Record<string, number>> = Object.freeze(${JSON.stringify(Object.fromEntries(Object.entries(manifest.glyphs).map(([name, file]) => [name, sizes[file]])), null, 2)});\n`;
const generated = output + sizeOutput;
const target = new URL('../../src/shared/paint-bitmaps.ts', root);
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== generated) throw new Error('Paint bitmap catalog is stale.');
} else writeFileSync(target, generated);
console.log(`${manifest.fugueFiles.length} Fugue + ${manifest.classicSources.length} classic + ${illustrated.sources.length} illustrated source hashes, ${Object.keys(images).length} native bitmaps and ${Object.keys(manifest.glyphs).length} mappings verified.`);
console.log(`${xp.tools.length + xp.commands.length} original Windows XP-style icons active (MIT).`);
